// EXAMPLE: Cách thêm User Status vào Right Sidebar (Friends List)
// File: components/right-sidebar.tsx

import { UserStatusIndicator } from "@/components/ui/user-status-indicator"
import { useUserStatus } from "@/lib/contexts/UserStatusContext"
import { UserStatus } from "@/lib/types/userStatus"

export function RightSidebar() {
  const { getUserStatus } = useUserStatus()
  const [friends, setFriends] = useState([])

  // Load friends data...

  return (
    <div className="right-sidebar">
      <h3 className="font-semibold mb-4">Suggestions For You</h3>

      {friends.map((friend) => {
        // Lấy status của friend này
        const friendStatus = getUserStatus(friend.id)

        return (
          <div key={friend.id} className="flex items-center gap-3 mb-4">
            {/* Avatar với Status */}
            <div className="relative">
              <Avatar className="w-10 h-10">
                <AvatarImage src={friend.avatarUrl} />
                <AvatarFallback>{friend.username[0]}</AvatarFallback>
              </Avatar>

              {/* Status indicator */}
              <UserStatusIndicator 
                status={friendStatus?.status || UserStatus.OFFLINE}
                size="sm"
                className="absolute bottom-0 right-0 border-2 border-background"
              />
            </div>

            {/* User info */}
            <div className="flex-1 min-w-0">
              <p className="text-sm font-semibold truncate">{friend.username}</p>
              <p className="text-xs text-muted-foreground truncate">
                {friendStatus?.status === UserStatus.ONLINE && "Đang hoạt động"}
                {friendStatus?.status === UserStatus.AWAY && "Vắng mặt"}
                {friendStatus?.status === UserStatus.OFFLINE && formatLastSeen(friendStatus.lastSeenAt)}
              </p>
            </div>

            {/* Follow button */}
            <button className="text-xs text-[#0095f6] font-semibold hover:text-[#00376b]">
              Follow
            </button>
          </div>
        )
      })}
    </div>
  )
}

// Helper function to format last seen
function formatLastSeen(lastSeenAt?: string) {
  if (!lastSeenAt) return "Không hoạt động"

  const lastSeen = new Date(lastSeenAt)
  const now = new Date()
  const diffMs = now.getTime() - lastSeen.getTime()
  const diffMins = Math.floor(diffMs / 60000)
  const diffHours = Math.floor(diffMs / 3600000)
  const diffDays = Math.floor(diffMs / 86400000)

  if (diffMins < 1) return "Vừa xem"
  if (diffMins < 60) return `${diffMins} phút trước`
  if (diffHours < 24) return `${diffHours} giờ trước`
  if (diffDays < 7) return `${diffDays} ngày trước`
  return "Lâu rồi"
}

